                : { ...(args?.data || {}), tenantId: tid };
              return method.call(t, { ...(args || {}), data });
            };
          }
          if (WITH_WHERE.has(name)) {
            return (args?: any) => method.call(t, { ...(args || {}), where: mergeWhere(args?.where, tid) });
          }
