              const found = await model.findFirst({ where: mergeWhere(args?.where, tid) });
              if (found) return model.update({ where: { id: found.id }, data: args?.update || {} });
              return model.create({ data: { ...(args?.create || {}), tenantId: tid } });
            };
          }
          return method;
        },
      });
    },
  });
  return proxy;
}
```

