import { Router } from 'express';
import { z } from 'zod';
import prisma from '../lib/prisma';
import { scoped } from '../lib/tenant';
import { authenticate, validate } from '../middleware';

const router = Router();
router.use(authenticate);

const chatMessageSchema = z.object({
  senderId: z.string().min(1),
  senderName: z.string().min(1),
  message: z.string().min(1),
  pacienteId: z.string().min(1),
  senderRole: z.enum(['RESPONSAVEL', 'STAFF']).optional(),
});

// Conversation list for the staff side: one thread per patient, with unread badge
router.get('/conversations', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const messages = await db.chatMessage.findMany({
    orderBy: { createdAt: 'asc' },
    include: { paciente: true },
  });

  const grouped = new Map<string, any>();
  for (const m of messages) {
    const p = m.paciente;
    if (!p) continue;
    const key = p.id;
    if (!grouped.has(key)) {
      grouped.set(key, {
        pacienteId: p.id,
        patientName: p.name,
        patientInitials: p.initials || p.name.slice(0, 2).toUpperCase(),
        patientColor: p.color || '#007F80',
        unreadCount: 0,
        lastMessage: m.message,
        lastSenderName: m.senderName,
        lastAt: m.createdAt,
      });
    }
    const entry = grouped.get(key);
    entry.lastMessage = m.message;
    entry.lastSenderName = m.senderName;
    entry.lastAt = m.createdAt;
  }

  // Unread = messages sent by the RESPONSAVEL that staff hasn't read yet
  const unread = await db.chatMessage.findMany({
    where: { senderRole: 'RESPONSAVEL', readByStaff: false },
    select: { pacienteId: true },
  });
  for (const u of unread) {
    const entry = grouped.get(u.pacienteId);
    if (entry) entry.unreadCount += 1;
  }

  const conversations = Array.from(grouped.values()).sort(
    (a, b) => new Date(b.lastAt).getTime() - new Date(a.lastAt).getTime()
  );

  res.json({ data: conversations, total: conversations.length });
});

// Mark a conversation as read by staff (called when the staff opens a thread)
router.post('/conversations/:pacienteId/read', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  await db.chatMessage.updateMany({
    where: { pacienteId: req.params.pacienteId, senderRole: 'RESPONSAVEL', readByStaff: false },
    data: { readByStaff: true },
  });
  res.json({ message: 'Conversa marcada como lida' });
});

// Send message as staff
router.post('/send', async (req: any, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { pacienteId, message } = req.body;
  if (!pacienteId || !message || !message.trim()) {
    return res.status(400).json({ error: 'Paciente e mensagem são obrigatórios' });
  }

  const user = req.user;
  if (!user) return res.status(401).json({ error: 'Não autenticado' });

  const dbUser = await prisma.user.findUnique({ where: { id: user.id } });
  const senderName = dbUser?.name || user.name || 'Equipe';

  const chatMessage = await db.chatMessage.create({
    data: {
      senderId: user.id,
      senderName,
      senderRole: 'STAFF',
      message,
      pacienteId,
      readByStaff: true,
    },
  });

  // Notify the responsible (guardian) that there's a new message
  const patient = await db.paciente.findUnique({
    where: { id: pacienteId },
    include: { responsible: true },
  });
  if (patient?.responsible?.userId) {
    await db.notification.create({
      data: {
        userId: patient.responsible.userId,
        title: 'Nova mensagem da equipe',
        message: `${senderName} respondeu no chat de ${patient.name}`,
        type: 'message',
      },
    });
  }

  res.status(201).json(chatMessage);
});

router.get('/', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { pacienteId } = req.query;
  const where: any = {};
  if (pacienteId) where.pacienteId = pacienteId;
  const messages = await db.chatMessage.findMany({ where, orderBy: { createdAt: 'asc' }, include: { paciente: true } });
  res.json({ data: messages, total: messages.length });
});

router.get('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const message = await db.chatMessage.findUnique({ where: { id: req.params.id }, include: { paciente: true } });
  if (!message) return res.status(404).json({ error: 'Mensagem não encontrada' });
  res.json(message);
});

router.post('/', validate(chatMessageSchema), async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const message = await db.chatMessage.create({ data: req.body });
  res.status(201).json(message);
});

router.put('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const message = await db.chatMessage.update({ where: { id: req.params.id }, data: req.body });
  res.json(message);
});

router.delete('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  await db.chatMessage.delete({ where: { id: req.params.id } });
  res.status(204).send();
});

export default router;

import { Router } from 'express';
import { z } from 'zod';
import prisma from '../lib/prisma';
import { scoped } from '../lib/tenant';
import { authenticate, validate } from '../middleware';

const router = Router();
router.use(authenticate);

const appointmentSchema = z.object({
  pacienteId: z.string().min(1),
  patientName: z.string().min(1),
  date: z.string().min(1),
  startTime: z.string().min(1),
  endTime: z.string().min(1),
  type: z.string().optional(),
  status: z.string().optional(),
  notes: z.string().optional(),
  color: z.string().optional(),
  autorId: z.string().optional(),
});

router.get('/', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { search, status, date } = req.query;
  const where: any = {};
  if (search) where.patientName = { contains: search };
  if (status) where.status = status;
  if (date) where.date = date;
  const appointments = await db.appointment.findMany({ where, orderBy: { date: 'asc' }, include: { paciente: true, autor: true } });
  res.json({ data: appointments, total: appointments.length });
});

router.get('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const appointment = await db.appointment.findUnique({ where: { id: req.params.id }, include: { paciente: true, autor: true } });
  if (!appointment) return res.status(404).json({ error: 'Agendamento não encontrado' });
  res.json(appointment);
});

router.post('/', validate(appointmentSchema), async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const appointment = await db.appointment.create({ data: req.body });
  res.status(201).json(appointment);
});

router.put('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const appointment = await db.appointment.update({ where: { id: req.params.id }, data: req.body });
  res.json(appointment);
});

// Transições de status permitidas para a equipe
const STATUS_TRANSITIONS: Record<string, string[]> = {
  PENDENTE: ['CONFIRMADO', 'CANCELADO'],
  CONFIRMADO: ['CONCLUIDO', 'CANCELADO'],
  CANCELADO: ['CONFIRMADO'],
  CONCLUIDO: [],
};

// Atualiza o status de um agendamento e notifica o responsável
router.put('/:id/status', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { status } = req.body;
  if (!status) return res.status(400).json({ error: 'Status é obrigatório' });

  const appointment = await db.appointment.findUnique({
    where: { id: req.params.id },
    include: { paciente: { include: { responsible: true } } },
  });
  if (!appointment) return res.status(404).json({ error: 'Agendamento não encontrado' });

  const allowed = STATUS_TRANSITIONS[appointment.status] || [];
  if (!allowed.includes(status)) {
    return res.status(400).json({
      error: `Transição inválida: ${appointment.status} → ${status}`,
      allowed,
    });
  }

  const updated = await db.appointment.update({
    where: { id: appointment.id },
    data: { status },
  });

  // Notifica o responsável (app + WhatsApp best-effort)
  const responsible = appointment.paciente?.responsible;
  if (responsible?.userId) {
    const labels: Record<string, string> = {
      CONFIRMADO: 'Agendamento confirmado',
      CANCELADO: 'Agendamento cancelado',
      CONCLUIDO: 'Agendamento finalizado',
    };
    const title = labels[status] || 'Agendamento atualizado';
    const message = `${title}: ${appointment.patientName} (${appointment.date} ${appointment.startTime})`;

    await db.notification.create({
      data: {
        userId: responsible.userId,
        title,
        message,
        type: 'appointment',
      },
    });

    const { sendWhatsAppMessage } = await import('./whatsapp');
    try {
      await sendWhatsAppMessage(responsible.phone || '', `🗓️ ${title}: ${appointment.patientName} (${appointment.date} ${appointment.startTime})`, req.user?.tenantId);
      console.log(`[WHATSAPP] Notificação de status enviada para ${responsible.name}`);
    } catch (error: any) {
      console.warn(`[WHATSAPP] Falha ao notificar status para ${responsible.name}: ${error.message}`);
    }
  }

  res.json(updated);
});

router.delete('/:id', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  await db.appointment.delete({ where: { id: req.params.id } });
  res.status(204).send();
});

export default router;

import { Router } from 'express';
import prisma from '../lib/prisma';
import { scoped } from '../lib/tenant';
import { authenticate } from '../middleware';

const router = Router();
router.use(authenticate);

// Staff (equipe) da clínica, via membership
async function getTenantStaff(tenantId: string) {
  const memberships = await prisma.membership.findMany({
    where: { tenantId, active: true },
    include: { user: true },
  });
  return memberships
    .map(m => m.user)
    .filter((u: any) => u.active && ['GESTOR', 'PROFISSIONAL', 'PSICOPEDAGOGO', 'SECRETARIA'].includes(u.role));
}

// Link responsible to patient by access code
router.post('/link', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { accessCode } = req.body;
  const userId = req.user?.id;

  if (!accessCode) {
    return res.status(400).json({ error: 'Código de acesso é obrigatório' });
  }

  const patient = await db.paciente.findFirst({
    where: { accessCode, active: true }
  });

  if (!patient) {
    return res.status(404).json({ error: 'Paciente não encontrado com esse código' });
  }

  // Find or create responsible for this user
  let responsible = await db.responsible.findFirst({
    where: { userId }
  });

  if (!responsible) {
    responsible = await db.responsible.create({
      data: {
        name: req.user?.name || 'Responsável',
        relationship: 'Responsável',
        userId,
        email: req.user?.email
      }
    });
  }

  // Link patient to responsible
  await db.paciente.update({
    where: { id: patient.id },
    data: { responsibleId: responsible.id }
  });

  res.json({ 
    message: 'Paciente vinculado com sucesso',
    patient: { id: patient.id, name: patient.name }
  });
});

// Get guardian's linked patients
router.get('/patients', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const userId = req.user?.id;

  const responsible = await db.responsible.findFirst({
    where: { userId }
  });

  if (!responsible) {
    return res.json({ data: [], total: 0 });
  }

  const patients = await db.paciente.findMany({
    where: { responsibleId: responsible.id, active: true },
    include: { school: true }
  });

  res.json({ data: patients, total: patients.length });
});

// Get shared evolutions for a patient
router.get('/evolutions/:patientId', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { patientId } = req.params;
  const userId = req.user?.id;

  // Verify guardian has access to this patient
  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) {
    return res.status(403).json({ error: 'Acesso negado' });
  }

  const patient = await db.paciente.findFirst({
    where: { id: patientId, responsibleId: responsible.id }
  });

  if (!patient) {
    return res.status(403).json({ error: 'Acesso negado a este paciente' });
  }

  const records = await db.sessionRecord.findMany({
    where: { pacienteId: patientId, sharedWithGuardian: true },
    orderBy: { date: 'desc' }
  });

  res.json({ data: records, total: records.length });
});

// Get financial info for a patient (only RECEITA/shared)
router.get('/financial/:patientId', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { patientId } = req.params;
  const userId = req.user?.id;

  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) {
    return res.status(403).json({ error: 'Acesso negado' });
  }

  const patient = await db.paciente.findFirst({
    where: { id: patientId, responsibleId: responsible.id }
  });

  if (!patient) {
    return res.status(403).json({ error: 'Acesso negado a este paciente' });
  }

  const transactions = await db.transaction.findMany({
    where: { patientId, type: 'RECEITA' },
    orderBy: { createdAt: 'desc' }
  });

  res.json({ data: transactions, total: transactions.length });
});

// Get shared documents for a patient
router.get('/documents/:patientId', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const { patientId } = req.params;
  const userId = req.user?.id;

  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) {
    return res.status(403).json({ error: 'Acesso negado' });
  }

  const patient = await db.paciente.findFirst({
    where: { id: patientId, responsibleId: responsible.id }
  });

  if (!patient) {
    return res.status(403).json({ error: 'Acesso negado a este paciente' });
  }

  const documents = await db.document.findMany({
    where: { pacienteId: patientId, isShared: true },
    orderBy: { createdAt: 'desc' }
  });

  res.json({ data: documents, total: documents.length });
});

// Upload document as guardian
router.post('/documents', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const userId = req.user?.id;
  const { pacienteId, name, category, fileUrl, size } = req.body;

  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) {
    return res.status(403).json({ error: 'Acesso negado' });
  }

  const document = await db.document.create({
    data: {
      name,
      pacienteId,
      category: category || 'ESCOLA',
      uploadedBy: 'guardian',
      fileUrl,
      size,
      isShared: false,
      autorId: userId
    }
  });

  res.status(201).json(document);
});

// Request appointment
router.post('/appointments', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const userId = req.user?.id;
  const { pacienteId, date, startTime, endTime, notes } = req.body;

  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) {
    return res.status(403).json({ error: 'Acesso negado' });
  }

  const patient = await db.paciente.findFirst({
    where: { id: pacienteId, responsibleId: responsible.id }
  });

  if (!patient) {
    return res.status(403).json({ error: 'Acesso negado a este paciente' });
  }

  const appointment = await db.appointment.create({
    data: {
      pacienteId,
      patientName: patient.name,
      date,
      startTime,
      endTime,
      notes: `Solicitado pelo responsável: ${notes || ''}`,
      status: 'PENDENTE',
      autorId: userId
    }
  });

  // Create notification for professional - find the professional from patient's sessions
  const patientSessions = await db.sessao.findMany({
    where: { pacienteId },
    select: { psicopedagogoId: true },
    take: 1
  });
  const professionalId = patientSessions[0]?.psicopedagogoId;

  if (professionalId) {
    await db.notification.create({
      data: {
        userId: professionalId,
        title: 'Nova solicitação de agendamento',
        message: `${responsible.name} solicitou agendamento para ${patient.name}`,
        type: 'appointment'
      }
    });
  }

  res.status(201).json(appointment);
});

// Get all upcoming appointments for guardian's patients
router.get('/appointments', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const userId = req.user?.id;
  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) return res.json({ data: [], total: 0 });

  const patients = await db.paciente.findMany({
    where: { responsibleId: responsible.id, active: true }
  });
  const patientIds = patients.map(p => p.id);

  const today = new Date().toISOString().split('T')[0];
  const appointments = await db.appointment.findMany({
    where: {
      pacienteId: { in: patientIds },
      date: { gte: today },
      status: { in: ['CONFIRMADO', 'PENDENTE'] }
    },
    orderBy: { date: 'asc' },
    include: { paciente: true }
  });

  res.json({ data: appointments, total: appointments.length });
});

// Helper: busca um agendamento que pertence aos pacientes do responsável
async function findGuardianAppointment(userId: string, appointmentId: string, tenantId?: string) {
  const db = scoped(prisma, tenantId);
  const responsible = await db.responsible.findFirst({ where: { userId } });
  if (!responsible) return null;

  const patients = await db.paciente.findMany({
    where: { responsibleId: responsible.id, active: true },
    select: { id: true },
  });

  return db.appointment.findFirst({
    where: { id: appointmentId, pacienteId: { in: patients.map(p => p.id) } },
    include: { paciente: true },
  });
}

// Notifica a equipe sobre cancelamento/reagendamento feito pelo responsável
async function notifyStaffOnGuardianAction(tenantId: string, title: string, message: string) {
  const db = scoped(prisma, tenantId);
  const staff = await getTenantStaff(tenantId);

  await db.notification.createMany({
    data: staff.map(u => ({ userId: u.id, title, message, type: 'appointment' }))
  });

  const { sendWhatsAppMessage } = await import('./whatsapp');
  for (const u of staff) {
    if (!u.phone || !u.phoneIsWhatsApp) continue;
    try {
      await sendWhatsAppMessage(u.phone, `🗓️ ${title}: ${message}`, tenantId);
      console.log(`[WHATSAPP] ${title} notificado para ${u.name}`);
    } catch (error: any) {
      console.warn(`[WHATSAPP] Falha ao notificar ${u.name}: ${error.message}`);
    }
  }
}

// Responsável cancela um agendamento (PENDENTE ou CONFIRMADO)
router.put('/appointments/:id/cancel', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const userId = req.user?.id;
  const appointment = await findGuardianAppointment(userId, req.params.id, req.user?.tenantId);
  if (!appointment) return res.status(404).json({ error: 'Agendamento não encontrado' });

  if (!['PENDENTE', 'CONFIRMADO'].includes(appointment.status)) {
    return res.status(400).json({ error: `Não é possível cancelar um agendamento ${appointment.status}` });
  }

  const updated = await db.appointment.update({
    where: { id: appointment.id },
    data: { status: 'CANCELADO', notes: `${appointment.notes || ''} | Cancelado pelo responsável`.trim() },
  });

  await notifyStaffOnGuardianAction(
    req.user!.tenantId!,
    'Agendamento cancelado pelo responsável',
    `${appointment.paciente?.name || appointment.patientName} (${appointment.date} ${appointment.startTime})`
  );

  res.json(updated);
});

// Responsável modifica (reagenda) um agendamento — volta para PENDENTE para a equipe re-confirmar
router.put('/appointments/:id/reschedule', async (req, res) => {
  const db = scoped(prisma, req.user?.tenantId);
  const userId = req.user?.id;
  const { date, startTime, notes } = req.body;
  if (!date) return res.status(400).json({ error: 'Nova data é obrigatória' });

  const appointment = await findGuardianAppointment(userId, req.params.id, req.user?.tenantId);
  if (!appointment) return res.status(404).json({ error: 'Agendamento não encontrado' });

  if (!['PENDENTE', 'CONFIRMADO'].includes(appointment.status)) {
    return res.status(400).json({ error: `Não é possível modificar um agendamento ${appointment.status}` });
  }

  const start = startTime || appointment.startTime;
  const endTime = String(parseInt(start.split(':')[0]) + 1).padStart(2, '0') + ':' + start.split(':')[1];

  const updated = await db.appointment.update({
    where: { id: appointment.id },
    data: {
      date,
      startTime: start,
      endTime,
      status: 'PENDENTE',
      notes: `${appointment.notes || ''} | Reagendado pelo responsável: ${date} ${start}${notes ? ` (${notes})` : ''}`.trim(),
    },
  });

  await notifyStaffOnGuardianAction(
